  ('dept-education-office', 'b01-f00-r01', 'اداره آموزش', 'education-office', 'واحد نمونه برای نمایش خدمات آموزشی. این توضیح نمونه است و اطلاعات رسمی دانشگاه نیست.', null, null, array['education', 'education office', 'آموزش', 'آموزشی']::text[], true, true),
  ('dept-student-affairs', 'b01-f00-r02', 'امور دانشجویی', 'student-affairs', 'واحد نمونه برای نمایش خدمات رفاهی و فرهنگی دانشجویان. این توضیح نمونه است و اطلاعات رسمی دانشگاه نیست.', null, null, array['student affairs', 'student', 'دانشجویی', 'رفاه']::text[], true, true),
  ('dept-finance-office', 'b01-f01-r01', 'امور مالی', 'finance-office', 'واحد نمونه برای نمایش خدمات مالی و شهریه. این توضیح نمونه است و اطلاعات رسمی دانشگاه نیست.', null, null, array['finance', 'finance office', 'مالی', 'حسابداری']::text[], true, true),
  ('dept-library', 'b01-f01-r02', 'کتابخانه', 'library', 'واحد نمونه برای نمایش خدمات کتابخانه. این توضیح نمونه است و اطلاعات رسمی دانشگاه نیست.', null, null, array['library', 'کتابخانه', 'کتاب']::text[], true, true),
  ('dept-secretariat', 'b01-f02-r01', 'دبیرخانه', 'secretariat', 'واحد نمونه برای نمایش ثبت و ارجاع مکاتبات اداری. این توضیح نمونه است و اطلاعات رسمی دانشگاه نیست.', null, null, array['secretariat', 'دبیرخانه', 'مکاتبات', 'اداری']::text[], true, true),
  ('dept-archive', 'b01-f02-r01', 'بایگانی', 'archive', 'واحد نمونه که در همان اتاق دبیرخانه قرار دارد (نمونه‌ای از چند واحد در یک اتاق). این توضیح نمونه است و اطلاعات رسمی دانشگاه نیست.', null, null, array['archive', 'بایگانی', 'سوابق']::text[], true, true),
  ('dept-it-center', 'b01-f02-r02', 'مرکز فناوری اطلاعات', 'it-center', 'واحد نمونه برای نمایش خدمات شبکه و حساب کاربری. این توضیح نمونه است و اطلاعات رسمی دانشگاه نیست.', null, null, array['it', 'it center', 'فناوری اطلاعات', 'کامپیوتر']::text[], true, true)
